// Paso 233 · v0.44.0 · Pantallas Subvenciones (ficha, concesión, cobro, reintegrable, imputación del cierre y deshacer) y ECPN (partes A y B, Excel)
// Cambia solo los trozos necesarios (con unas líneas de contexto) y crea los ficheros nuevos.
// Uso (desde la carpeta frontend):   node aplicar-paso233-web.mjs
// Se puede ejecutar dos veces sin problema. Si algo no encaja, lo dice y no toca ese trozo.
import fs from 'node:fs'

const NEW_FILES = {
  "src/components/EquityStatement.jsx": "import { useEffect, useState } from 'react'\nimport { supabase } from '../supabase'\nimport { useI18n } from '../i18n'\nimport { money } from '../format'\nimport { workYear } from '../workDate'\nimport { partA, partB, paren } from '../grants'\nimport { downloadXlsx, fileName } from '../exportXlsx'\nimport Sources from './Sources'\nimport ErrorBox from './ErrorBox'\nimport ReportActions from './ReportActions'\n\n// ESTADO DE CAMBIOS EN EL PATRIMONIO NETO (v0.44.0; PGC, 3.ª parte): parte A, ingresos y gastos reconocidos (el\n// resultado + lo imputado directamente al patrimonio neto − lo transferido a resultados), y parte B, el estado total\n// por columnas, del saldo inicial al final, comprobado contra el patrimonio neto del balance. Lo calcula la base de\n// datos (erp.equity_statement, 0065); para todas las empresas (el PGC de pymes no exige la parte A, pero se enseña).\nexport default function EquityStatement({ company }) {\n  const { t, language } = useI18n()\n  const [years, setYears] = useState([])\n  const [year, setYear] = useState(() => workYear(company))\n  const [data, setData] = useState(null)\n  const [error, setError] = useState('')\n  const m = (v) => paren(v, (x) => money(x, language))\n\n  useEffect(() => {\n    supabase.from('fiscal_years').select('year').eq('company_id', company.id).order('year')\n      .then(({ data: d, error: e }) => {\n        if (e) return setError(e.message)\n        setYears(d.map((r) => r.year))\n        if (d.length && !d.some((r) => r.year === Number(year))) setYear(d[d.length - 1].year)\n      })\n  }, [company.id])   // eslint-disable-line react-hooks/exhaustive-deps\n\n  useEffect(() => {\n    let alive = true\n    supabase.rpc('equity_statement', { p_company: company.id, p_year: Number(year) }).then(({ data: d, error: e }) => {\n      if (!alive) return\n      if (e) { setData(null); return setError(e.code === 'PGRST202' ? t('ecpn.dbMissing') : e.message) }\n      setError(''); setData(d)\n    })\n    return () => { alive = false }\n  }, [company.id, year])   // eslint-disable-line react-hooks/exhaustive-deps\n\n  const a = data ? partA(data.part_a) : []\n  const b = data ? partB(data) : { cols: [], rows: [] }\n  const exportExcel = () => downloadXlsx({\n    title: `${t('ecpn.title')} · ${company.name ?? ''}`, subtitle: `${t('year')} ${year}`, sheet: 'ECPN',\n    file: fileName('ECPN', company.name, year),\n    columns: [{ header: t('ecpn.concept'), key: 'label', type: 'text', width: 60 }, ...b.cols.map((c) => ({ header: t(`ecpn.col.${c}`), key: c, type: 'money' })),\n      { header: t('ecpn.col.total'), key: 'total', type: 'money' }],\n    rows: [\n      ...a.map((r) => ({ label: `A · ${t(`ecpn.a.${r.key}`)}`, total: r.amount })),\n      {},\n      ...b.rows.map((r) => ({ label: `B · ${t(`ecpn.row.${r.key}`)}`, ...r.values, total: r.total })),\n    ],\n  })\n\n  return (\n    <>\n      <section className=\"tarjeta\">\n        <div className=\"titulo-modelo\"><h2>{t('ecpn.title')}</h2><Sources ids={['pgc']} /></div>\n        <p className=\"ayuda\">{t('ecpn.intro')}</p>\n        <div className=\"rejilla-tres\">\n          <label>{t('year')}\n            <select value={year} onChange={(e) => setYear(Number(e.target.value))}>\n              {years.map((y) => <option key={y} value={y}>{y}</option>)}\n            </select>\n          </label>\n        </div>\n        <ErrorBox error={error} company={company} />\n        {data && <ReportActions onExcel={exportExcel} info={`${company.name ?? ''} · ${t('year')} ${year}`} />}\n      </section>\n\n      {data && (\n        <section className=\"tarjeta\">\n          <h3>{t('ecpn.partA')}</h3>\n          <p className=\"ayuda\">{t('ecpn.partAHelp')}</p>\n          <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('ecpn.partA')}>\n            <table className=\"informe\">\n              <thead><tr><th scope=\"col\">{t('ecpn.concept')}</th><th scope=\"col\" className=\"num\">{year}</th></tr></thead>\n              <tbody>{a.map((r) => (\n                <tr key={r.key} className={r.level === 0 ? 'total' : ''}>\n                  <td style={{ paddingLeft: r.level ? '1.5rem' : undefined }}>{t(`ecpn.a.${r.key}`)}</td><td className=\"num\">{m(r.amount)}</td>\n                </tr>))}</tbody>\n            </table>\n          </div>\n        </section>\n      )}\n\n      {data && (\n        <section className=\"tarjeta\">\n          <h3>{t('ecpn.partB')}</h3>\n          <p className=\"ayuda\">{t('ecpn.partBHelp')}</p>\n          <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('ecpn.partB')}>\n            <table className=\"informe\">\n              <thead><tr><th scope=\"col\">{t('ecpn.concept')}</th>{b.cols.map((c) => <th key={c} scope=\"col\" className=\"num\">{t(`ecpn.col.${c}`)}</th>)}\n                <th scope=\"col\" className=\"num\">{t('ecpn.col.total')}</th></tr></thead>\n              <tbody>{b.rows.map((r) => (\n                <tr key={r.key} className={['start', 'end'].includes(r.key) ? 'total' : ''}>\n                  <td>{t(`ecpn.row.${r.key}`).replace('{y}', year)}</td>\n                  {b.cols.map((c) => <td key={c} className=\"num\">{r.values[c] ? m(r.values[c]) : '—'}</td>)}\n                  <td className=\"num\">{m(r.total)}</td>\n                </tr>))}</tbody>\n            </table>\n          </div>\n          <p className={data.ok ? 'exito' : 'aviso'} role=\"status\">\n            {data.ok ? '✓ ' : '⚠ '}{t(data.ok ? 'ecpn.ok' : 'ecpn.notOk').replace('{m}', money(data.balance_net_worth, language)).replace('{e}', money(data.end, language))}\n          </p>\n        </section>\n      )}\n    </>\n  )\n}\n",
  "src/components/Grants.jsx": "import { useEffect, useState } from 'react'\nimport { supabase } from '../supabase'\nimport { useI18n } from '../i18n'\nimport { money, shortDate } from '../format'\nimport { companyPath } from '../router'\nimport { workDate } from '../workDate'\nimport { KINDS, assetShare, balanced, concessionEntry, emptyForm, imputationEntry, payload, unconditionalEntry, undoable } from '../grants'\nimport Link from './Link'\nimport Sources from './Sources'\nimport ErrorBox from './ErrorBox'\n\n// SUBVENCIONES (v0.44.0): de capital y a la explotación (PGC, NRV 18.ª). La base de datos contabiliza (0064 y 0065):\n// la concesión al patrimonio neto (grupo 9) neta de su impuesto futuro (8301 / 479), o a resultados (740) si es a la\n// explotación; la reintegrable como deuda (522 / 172) hasta que se cumple la condición; y cada cierre la parte del año\n// a resultados (840 / 746) con la amortización del activo que financia. Al cierre del ejercicio los grupos 8 y 9 se\n// regularizan contra la 130, y la baja del activo en Inmovilizado imputa lo que quede.\n// En BC y SAP no hay módulo estándar de subvenciones: se registran en el diario general.\nexport default function Grants({ company, readOnly }) {\n  const { t, language } = useI18n()\n  const today = workDate(company)\n  const [grants, setGrants] = useState(null)\n  const [assets, setAssets] = useState([])\n  const [selected, setSelected] = useState(null)\n  const [events, setEvents] = useState([])\n  const [entryNos, setEntryNos] = useState({})\n  const [form, setForm] = useState(() => emptyForm(today))\n  const [opDate, setOpDate] = useState(today)\n  const [yeDate, setYeDate] = useState(`${today.slice(0, 4)}-12-31`)\n  const [ye, setYe] = useState(null)\n  const [confirming, setConfirming] = useState(null)   // 'create' | 'collect' | 'unconditional' | 'rest' | 'yearEnd' | id\n  const [busy, setBusy] = useState(false)\n  const [error, setError] = useState('')\n  const [done, setDone] = useState('')\n  const [refresh, setRefresh] = useState(0)\n  const m = (v) => money(v, language)\n  const canWrite = !readOnly\n\n  useEffect(() => {\n    let alive = true\n    Promise.all([\n      supabase.rpc('grant_status', { p_company: company.id }),\n      supabase.from('v_fixed_assets').select('id, code, name, cost, status, asset_account_no').eq('company_id', company.id).order('code'),\n    ]).then(([g, a]) => {\n      if (!alive) return\n      if (g.error) return setError(g.error.code === 'PGRST202' ? t('gr.dbMissing') : g.error.message)\n      setGrants(g.data ?? []); setAssets((a.data ?? []).filter((x) => x.status === 'active'))\n    })\n    return () => { alive = false }\n  }, [company.id, refresh])   // eslint-disable-line react-hooks/exhaustive-deps\n\n  useEffect(() => {\n    if (!selected) return undefined\n    let alive = true\n    supabase.from('grant_events').select('id, grant_id, seq, kind, event_date, amount, tax_amount, entry_id, status').eq('grant_id', selected).order('seq', { ascending: false })\n      .then(async ({ data }) => {\n        const ev = (data ?? []).filter((r) => r.grant_id === selected)\n        const ids = ev.map((r) => r.entry_id).filter(Boolean)\n        const { data: je } = ids.length ? await supabase.from('journal_entries').select('id, entry_no, posting_date').in('id', ids) : { data: [] }\n        if (!alive) return\n        setEvents(ev); setEntryNos(Object.fromEntries((je ?? []).map((r) => [r.id, [String(r.posting_date).slice(0, 4), r.entry_no]])))\n      })\n    return () => { alive = false }\n  }, [selected, refresh])\n\n  useEffect(() => {\n    let alive = true\n    supabase.rpc('grant_year_end_preview', { p_company: company.id, p_date: yeDate })\n      .then(({ data, error }) => { if (alive) setYe(error ? null : data) })\n    return () => { alive = false }\n  }, [company.id, yeDate, refresh])\n\n  async function run(fn, args, ok) {\n    setBusy(true); setError(''); setDone('')\n    const { data, error } = await supabase.rpc(fn, args)\n    setBusy(false); setConfirming(null)\n    if (error) return setError(error.message)\n    ok?.(data); setRefresh((x) => x + 1)\n  }\n  const create = () => run('grant_create', { p: payload(form, company.id) }, (d) => {\n    setDone(t('gr.created').replace('{c}', d.code).replace('{n}', d.entry_no)); setSelected(d.grant_id); setForm(emptyForm(today))\n  })\n  const collect = () => run('grant_collect', { p: { grant_id: selected, date: opDate } }, (d) => setDone(t('gr.collected').replace('{n}', d.entry_no)))\n  const uncond = () => run('grant_unconditional', { p: { grant_id: selected, date: opDate } }, (d) => setDone(t('gr.unconditionalDone').replace('{n}', d.entry_no)))\n  const rest = () => run('grant_impute_rest', { p: { grant_id: selected, date: opDate } }, (d) => setDone(t('gr.restDone').replace('{m}', m(d.amount)).replace('{n}', d.entry_no)))\n  const undo = () => run('grant_cancel', { p_grant: selected }, (d) => setDone(t('gr.undone').replace('{k}', t(`gr.ev.${d.kind}`))))\n  const yearEnd = () => run('grant_year_end', { p_company: company.id, p_date: yeDate }, (d) => setDone(t('gr.yearEndDone').replace('{n}', d.entries)))\n\n  const g = (grants ?? []).find((x) => x.grant_id === selected)\n  const lastId = undoable(events)\n  const preview = concessionEntry(form)\n  const asset = assets.find((a) => a.id === form.asset_id)\n  const field = (k, label, extra = {}) => (\n    <label>{label}<input inputMode=\"decimal\" value={form[k] ?? ''} onChange={(e) => setForm({ ...form, [k]: e.target.value })} {...extra} /></label>\n  )\n  const entryTable = (lines, caption) => (\n    <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={caption}>\n      <table className=\"informe\">\n        <caption>{caption}</caption>\n        <thead><tr><th scope=\"col\">{t('account')}</th><th scope=\"col\" className=\"num\">{t('debit')}</th><th scope=\"col\" className=\"num\">{t('credit')}</th></tr></thead>\n        <tbody>{lines.map((l) => (\n          <tr key={l.account + l.debit + l.credit}><td><span className=\"codigo\">{l.account}</span> {t(`gr.account.${l.account}`)}</td>\n            <td className=\"num\">{l.debit ? m(l.debit) : ''}</td><td className=\"num\">{l.credit ? m(l.credit) : ''}</td></tr>))}</tbody>\n      </table>\n      {!balanced(lines) && <p className=\"aviso\">{t('gr.unbalanced')}</p>}\n    </div>\n  )\n  const confirmBox = (key, text, action, label) => confirming === key && (\n    <div className=\"anular\" role=\"alertdialog\" aria-label={text}>\n      <p>{text}</p>\n      <div className=\"fila\">\n        <button type=\"button\" className=\"secundario\" onClick={() => setConfirming(null)}>{t('cancel')}</button>\n        <button type=\"button\" disabled={busy} onClick={action}>{label}</button>\n      </div>\n    </div>\n  )\n  const action = (key, label, onClick, text) => (confirming !== key\n    ? <button type=\"button\" className=\"secundario\" disabled={busy} onClick={() => setConfirming(key)}>{label}</button>\n    : confirmBox(key, text, onClick, label))\n  const entryLink = (id) => {\n    const [y, n] = entryNos[id] ?? []\n    return n ? <Link className=\"enlace\" to={companyPath(company.id, `asiento/${y}/${n}`)}>{n}</Link> : null\n  }\n\n  return (\n    <>\n      <section className=\"tarjeta subvenciones\">\n        <div className=\"titulo-modelo\"><h2>{t('gr.title')}</h2><Sources ids={['pgc']} /></div>\n        <p className=\"ayuda\">{t('gr.intro')}</p>\n        <ErrorBox error={error} company={company} />\n        {done && <p className=\"exito\" role=\"status\">✓ {done}</p>}\n      </section>\n\n      <section className=\"tarjeta\">\n        <h3>{t('gr.listTitle')}</h3>\n        {grants && grants.length === 0 && <p className=\"ayuda\">{t('gr.listNone')}</p>}\n        {grants && grants.length > 0 && (\n          <>\n            <p className=\"ayuda\">{t('gr.listHelp')}</p>\n            <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('gr.listTitle')}>\n              <table className=\"informe\">\n                <thead><tr><th scope=\"col\">{t('gr.col.code')}</th><th scope=\"col\">{t('gr.col.description')}</th><th scope=\"col\" className=\"num\">{t('gr.col.amount')}</th>\n                  <th scope=\"col\" className=\"num\">{t('gr.col.imputed')}</th><th scope=\"col\" className=\"num\">{t('gr.col.pending')}</th><th scope=\"col\" className=\"num\">{t('gr.col.deferred')}</th></tr></thead>\n                <tbody>{grants.map((x) => (\n                  <tr key={x.grant_id} className={x.grant_id === selected ? 'seleccionado' : ''}>\n                    <td><button type=\"button\" className=\"secundario codigo\" aria-pressed={x.grant_id === selected}\n                      aria-label={`${t(x.grant_id === selected ? 'gr.hide' : 'gr.see')} ${x.code}`} onClick={() => setSelected(x.grant_id === selected ? null : x.grant_id)}>{x.code}</button></td>\n                    <td>{x.description}<br /><small className=\"articulo\">{t(`gr.kind.${x.kind}`)}{x.grantor ? ` · ${x.grantor}` : ''}{x.asset_code ? ` · ${x.asset_code}` : ''}\n                      {x.refundable && !x.unconditional ? ` · ${t('gr.refundableBadge')}` : ''}{!x.collected ? ` · ${t('gr.notCollected')}` : ''}{x.status === 'imputed' ? ` · ${t('gr.imputedBadge')}` : ''}</small></td>\n                    <td className=\"num\">{m(x.amount)}</td>\n                    <td className=\"num\">{x.kind === 'capital' ? m(x.imputed) : ''}</td>\n                    <td className=\"num\">{x.kind === 'capital' ? m(x.pending) : ''}</td>\n                    <td className=\"num\">{x.kind === 'capital' ? m(x.deferred_tax) : ''}</td>\n                  </tr>))}</tbody>\n              </table>\n            </div>\n          </>\n        )}\n      </section>\n\n      {g && (\n        <section className=\"tarjeta\">\n          <h3>{g.code} · {g.description}</h3>\n          <p className=\"ayuda\">{t(`gr.detailHelp.${g.kind}`).replace('{a}', g.asset_code ? `${g.asset_code} · ${g.asset_name}` : '').replace('{r}', `${Number(g.tax_rate)} %`)}</p>\n          {canWrite && g.status === 'active' && (\n            <>\n              <div className=\"rejilla-tres\">\n                <label>{t('gr.f.opDate')}<input type=\"date\" value={opDate} onChange={(e) => { setConfirming(null); setOpDate(e.target.value) }} /></label>\n              </div>\n              {g.refundable && !g.unconditional && (\n                <>\n                  {entryTable(unconditionalEntry(g), t('gr.entry.unconditional'))}\n                  {action('unconditional', t('gr.unconditional'), uncond, t('gr.confirmUnconditional').replace('{d}', shortDate(opDate)))}\n                </>\n              )}\n              <div className=\"fila\">\n                {!g.collected && action('collect', t('gr.collect').replace('{m}', m(g.amount)), collect, t('gr.confirmCollect').replace('{m}', m(g.amount)).replace('{d}', shortDate(opDate)))}\n                {g.kind === 'capital' && g.unconditional && Number(g.pending) > 0 &&\n                  action('rest', t('gr.rest'), rest, t('gr.confirmRest').replace('{m}', m(g.pending)).replace('{d}', shortDate(opDate)))}\n              </div>\n              {g.kind === 'capital' && g.unconditional && <p className=\"ayuda\">{t('gr.restHelp')}</p>}\n            </>\n          )}\n\n          <h4>{t('gr.eventsTitle')}</h4>\n          <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('gr.eventsTitle')}>\n            <table className=\"informe\">\n              <thead><tr><th scope=\"col\">{t('gr.e.date')}</th><th scope=\"col\">{t('gr.e.kind')}</th><th scope=\"col\" className=\"num\">{t('gr.e.amount')}</th>\n                <th scope=\"col\" className=\"num\">{t('gr.e.tax')}</th><th scope=\"col\">{t('gr.e.entry')}</th><th scope=\"col\" aria-label={t('gr.undo')} /></tr></thead>\n              <tbody>{events.map((e) => (\n                <tr key={e.id} className={e.status === 'cancelled' ? 'excluido' : ''}>\n                  <td>{shortDate(e.event_date)}</td>\n                  <td>{t(`gr.ev.${e.kind}`)}{e.status === 'cancelled' && <span className=\"etiqueta etiqueta-texto\"> {t('gr.cancelled')}</span>}</td>\n                  <td className=\"num\">{m(e.amount)}</td><td className=\"num\">{Number(e.tax_amount) ? m(e.tax_amount) : ''}</td>\n                  <td>{e.entry_id ? entryLink(e.entry_id) : ''}</td>\n                  <td>\n                    {canWrite && e.id === lastId && confirming !== e.id && <button type=\"button\" className=\"secundario\" disabled={busy} onClick={() => setConfirming(e.id)}>↩ {t('gr.undo')}</button>}\n                    {confirmBox(e.id, t(e.kind === 'concession' ? 'gr.confirmUndoStart' : 'gr.confirmUndo').replace('{k}', t(`gr.ev.${e.kind}`)), undo, t('gr.undo'))}\n                  </td>\n                </tr>))}</tbody>\n            </table>\n          </div>\n          <p className=\"ayuda\">{t('gr.undoHelp')}</p>\n        </section>\n      )}\n\n      {canWrite && (\n        <section className=\"tarjeta\">\n          <h3>{t('gr.newTitle')}</h3>\n          <div className=\"rejilla-tres\">\n            <label>{t('gr.f.kind')}\n              <select value={form.kind} onChange={(e) => setForm({ ...form, kind: e.target.value })}>\n                {KINDS.map((k) => <option key={k} value={k}>{t(`gr.kind.${k}`)}</option>)}\n              </select>\n            </label>\n            <label>{t('gr.f.description')}<input maxLength={120} value={form.description} placeholder={t(`gr.f.descPh.${form.kind}`)} onChange={(e) => setForm({ ...form, description: e.target.value })} /></label>\n            <label>{t('gr.f.grantor')}<input maxLength={80} value={form.grantor} onChange={(e) => setForm({ ...form, grantor: e.target.value })} /></label>\n            {field('amount', t('gr.f.amount'))}\n            <label>{t('gr.f.date')}<input type=\"date\" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></label>\n            {form.kind === 'capital' && (\n              <label>{t('gr.f.asset')}\n                <select value={form.asset_id} onChange={(e) => setForm({ ...form, asset_id: e.target.value })}>\n                  <option value=\"\">{t('gr.f.choose')}</option>\n                  {assets.map((a) => <option key={a.id} value={a.id}>{a.code} · {a.name} ({m(a.cost)})</option>)}\n                </select>\n              </label>\n            )}\n            {form.kind === 'capital' && field('tax_rate', t('gr.f.taxRate'))}\n            {form.refundable && <label>{t('gr.f.conditionDue')}<input type=\"date\" value={form.condition_due} onChange={(e) => setForm({ ...form, condition_due: e.target.value })} /></label>}\n          </div>\n          <div className=\"opciones-subvencion\">\n            <label className=\"opcion\"><input type=\"checkbox\" checked={form.refundable} onChange={(e) => setForm({ ...form, refundable: e.target.checked })} /> {t('gr.f.refundable')}</label>\n            <label className=\"opcion\"><input type=\"checkbox\" checked={form.collected} onChange={(e) => setForm({ ...form, collected: e.target.checked })} /> {t('gr.f.collected')}</label>\n          </div>\n          <p className=\"ayuda\">{t(form.refundable ? 'gr.help.refundable' : `gr.help.${form.kind}`)}</p>\n          {form.kind === 'capital' && assets.length === 0 && <p className=\"aviso-modo\">📌 {t('gr.noAssets')} <Link className=\"enlace\" to={companyPath(company.id, 'assets')}>{t('nav.assets.label')} →</Link></p>}\n          {form.kind === 'capital' && asset && assetShare(form.amount, asset.cost) > 100 && <p className=\"aviso\" role=\"alert\">⚠ {t('gr.exceeds').replace('{m}', m(asset.cost))}</p>}\n          {form.kind === 'capital' && asset && assetShare(form.amount, asset.cost) <= 100 && <p className=\"ayuda\">{t('gr.assetPct').replace('{p}', assetShare(form.amount, asset.cost).toLocaleString(language === 'en' ? 'en-GB' : 'es-ES')).replace('{a}', asset.code)}</p>}\n          {preview.length > 0 && entryTable(preview, t('gr.entry.concession'))}\n          {confirming !== 'create'\n            ? <button type=\"button\" disabled={busy || preview.length === 0 || !form.description.trim() || !form.date || (form.kind === 'capital' && (!form.asset_id || (asset && assetShare(form.amount, asset.cost) > 100))) || (form.refundable && !form.condition_due)}\n                onClick={() => setConfirming('create')}>{t('gr.create')}</button>\n            : confirmBox('create', t('gr.confirmCreate').replace('{d}', shortDate(form.date)), create, t('gr.create'))}\n        </section>\n      )}\n\n      <section className=\"tarjeta\">\n        <h3>{t('gr.yearEndTitle')}</h3>\n        <p className=\"ayuda\">{t('gr.yearEndHelp')}</p>\n        <div className=\"rejilla-tres\">\n          <label>{t('gr.f.yearEndDate')}<input type=\"date\" value={yeDate} onChange={(e) => { setConfirming(null); setYeDate(e.target.value) }} /></label>\n        </div>\n        {ye && ye.grants.length === 0 && <p className=\"ayuda\">{t('gr.yearEndNone')}</p>}\n        {ye && ye.grants.length > 0 && (\n          <>\n            <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('gr.yearEndTitle')}>\n              <table className=\"informe\">\n                <thead><tr><th scope=\"col\">{t('gr.col.code')}</th><th scope=\"col\" className=\"num\">{t('gr.y.pct')}</th><th scope=\"col\" className=\"num\">{t('gr.y.imputation')}</th>\n                  <th scope=\"col\" className=\"num\">{t('gr.y.tax')}</th><th scope=\"col\">{t('gr.y.note')}</th></tr></thead>\n                <tbody>{ye.grants.map((x) => (\n                  <tr key={x.grant_id}>\n                    <td><span className=\"codigo\">{x.code}</span> {x.description}</td>\n                    <td className=\"num\">{x.pct != null ? `${Number(x.pct).toLocaleString(language === 'en' ? 'en-GB' : 'es-ES', { maximumFractionDigits: 2 })} %` : '—'}</td>\n                    <td className=\"num\">{Number(x.imputation) ? m(x.imputation) : '—'}</td>\n                    <td className=\"num\">{Number(x.tax) ? m(x.tax) : '—'}</td>\n                    <td>{x.depreciation_pending ? <span className=\"aviso\">⚠ {t('gr.y.depreciationPending').replace('{a}', x.asset_code)}</span>\n                      : !x.unconditional ? t('gr.y.refundable') : ''}</td>\n                  </tr>))}\n                  <tr className=\"total\"><td>{t('gr.y.total')}</td><td /><td className=\"num\">{m(ye.imputation_total)}</td><td className=\"num\">{m(ye.tax_total)}</td><td /></tr>\n                </tbody>\n              </table>\n            </div>\n            {Number(ye.imputation_total) > 0 && entryTable(imputationEntry(ye.imputation_total, ye.tax_total), t('gr.entry.imputation'))}\n          </>\n        )}\n        {ye && ye.depreciation_pending > 0 && <p className=\"aviso-modo\">📌 {t('gr.depreciateFirst')} <Link className=\"enlace\" to={companyPath(company.id, 'assets')}>{t('nav.assets.label')} →</Link></p>}\n        {canWrite && ye && ye.grants.length > 0 && (confirming !== 'yearEnd'\n          ? <button type=\"button\" disabled={busy || ye.depreciation_pending > 0 || (Number(ye.imputation_total) === 0 && Number(ye.tax_total) === 0)} onClick={() => setConfirming('yearEnd')}>{t('gr.yearEnd')}</button>\n          : confirmBox('yearEnd', t('gr.confirmYearEnd').replace('{d}', shortDate(yeDate)), yearEnd, t('gr.yearEnd')))}\n        {ye && ye.grants.length > 0 && !ye.depreciation_pending && Number(ye.imputation_total) === 0 && Number(ye.tax_total) === 0 && <p className=\"ayuda\">✓ {t('gr.yearEndUpToDate')}</p>}\n        <p className=\"ayuda\">{t('gr.closingHelp')} <Link className=\"enlace\" to={companyPath(company.id, 'ecpn')}>{t('nav.ecpn.label')} →</Link></p>\n      </section>\n    </>\n  )\n}\n",
  "src/grants.js": "// SUBVENCIONES Y ECPN (v0.44.0): cómo se enseña lo que hace la base de datos (0064 y 0065). Las reglas (NRV 18.ª y\n// 13.ª), la imputación con la amortización y el ECPN los calcula la base de datos; aquí se preparan los datos y se\n// dibujan los mismos asientos antes de contabilizar (tests/grants.test.js los compara con los supuestos S1 a S4).\nimport { parseAmount } from './practice'\n\nexport const KINDS = ['capital', 'operating']\n\nexport const emptyForm = (date = '') => ({\n  kind: 'capital', description: '', grantor: '', amount: '', date, refundable: false, condition_due: '', collected: false,\n  asset_id: '', tax_rate: '25',\n})\n\nconst num = (v) => (String(v ?? '').trim() === '' ? undefined : parseAmount(v))\nconst r2 = (v) => Math.round((Number(v) || 0) * 100) / 100\nconst L = (account, debit, credit) => ({ account, debit: r2(debit), credit: r2(credit) })\nconst clean = (lines) => lines.filter((l) => l.debit || l.credit)\n\n// Lo que se manda a erp.grant_create (los vacíos no se mandan)\nexport function payload(form, companyId) {\n  const p = { company_id: companyId, kind: form.kind, date: form.date, refundable: Boolean(form.refundable), collected: Boolean(form.collected) }\n  const set = (k, v) => { if (v !== undefined && v !== '' && !Number.isNaN(v)) p[k] = v }\n  set('description', String(form.description ?? '').trim())\n  set('grantor', String(form.grantor ?? '').trim())\n  set('amount', num(form.amount))\n  set('tax_rate', num(form.tax_rate))\n  if (form.refundable) set('condition_due', form.condition_due)\n  if (form.kind === 'capital') set('asset_id', form.asset_id)\n  return p\n}\n\n// ¿La condición vence en los 12 meses siguientes? (deuda a corto, 522; si no, 172)\nexport function shortTerm(date, due) {\n  if (!date || !due) return true\n  const limit = `${Number(date.slice(0, 4)) + 1}${date.slice(4)}`\n  return due <= limit\n}\n\n// Asiento de la concesión: 4708 (o el banco, si ya está cobrada) / 940 (capital) · 740 (explotación) · 522 / 172\n// (reintegrable) + el efecto impositivo de la de capital no reintegrable (8301 / 479)\nexport function concessionEntry(form) {\n  const amount = num(form.amount) ?? 0\n  if (amount <= 0) return []\n  const first = form.collected ? '572' : form.kind === 'capital' ? '4708' : '47089'\n  const credit = form.refundable ? (shortTerm(form.date, form.condition_due) ? '522' : '172') : form.kind === 'capital' ? '940' : '740'\n  const tax = form.kind === 'capital' && !form.refundable ? r2(amount * (num(form.tax_rate) ?? 25) / 100) : 0\n  return clean([L(first, amount, 0), L(credit, 0, amount), L('8301', tax, 0), L('479', 0, tax)])\n}\n\n// Se cumple la condición: 522 / 172 → 940 (capital, con su efecto impositivo) o 740 (explotación)\nexport function unconditionalEntry(g) {\n  if (!g) return []\n  const debt = shortTerm(g.grant_date, g.condition_due) ? '522' : '172'\n  const tax = g.kind === 'capital' ? r2(Number(g.amount) * Number(g.tax_rate) / 100) : 0\n  return clean([L(debt, g.amount, 0), L(g.kind === 'capital' ? '940' : '740', 0, g.amount), L('8301', tax, 0), L('479', 0, tax)])\n}\n\n// Imputación del cierre (o lo que queda, al dar de baja el activo): 840 / 746 y 479 / 8301\nexport const imputationEntry = (amount, tax) => clean([L('840', amount, 0), L('746', 0, amount), L('479', tax, 0), L('8301', 0, tax)])\n\n// Qué parte del coste del activo financia la subvención (%): ese % de cada amortización pasa a resultados\nexport const assetShare = (amount, cost) => (Number(cost) > 0 ? Math.round((num(amount) ?? 0) / Number(cost) * 10000) / 100 : 0)\n\n// El movimiento que se puede deshacer: el último contabilizado\nexport function undoable(events = []) {\n  return [...events].filter((e) => e.status === 'posted').sort((a, b) => Number(b.seq) - Number(a.seq))[0]?.id ?? null\n}\n\nexport const balanced = (lines) => lines.reduce((s, l) => s + Math.round(l.debit * 100) - Math.round(l.credit * 100), 0) === 0\n\n// ---------- ECPN ----------\n// Parte A: [{ key, amount, level }] en el orden del modelo del PGC (las de nivel 0 son totales)\nexport const PART_A = [['result', 0], ['b_grants', 1], ['b_tax', 1], ['b_other', 1], ['b_total', 0], ['c_grants', 1], ['c_tax', 1], ['c_total', 0], ['total', 0]]\nexport function partA(a = {}) {\n  return PART_A.filter(([k]) => k !== 'b_other' || Number(a.b_other)).map(([key, level]) => ({ key, level, amount: Number(a[key] ?? 0) }))\n}\n\n// Parte B: filas (saldo inicial, ingresos y gastos reconocidos, operaciones con socios, otras variaciones, saldo final)\n// × columnas (las que tienen movimientos) con su total\nexport const PART_B_ROWS = ['start', 'recognised', 'owners', 'other']\nexport function partB(data) {\n  const cols = data?.columns ?? []\n  const b = data?.part_b ?? {}\n  const rows = PART_B_ROWS.map((key) => {\n    const values = Object.fromEntries(cols.map((c) => [c, Number(b[key]?.[c] ?? 0)]))\n    return { key, values, total: r2(cols.reduce((s, c) => s + values[c], 0)) }\n  })\n  const end = Object.fromEntries(cols.map((c) => [c, r2(rows.reduce((s, r) => s + r.values[c], 0))]))\n  rows.push({ key: 'end', values: end, total: r2(cols.reduce((s, c) => s + end[c], 0)) })\n  return { cols, rows }\n}\n\n// Signo de las cuentas anuales: las cifras negativas entre paréntesis\nexport const paren = (v, fmt) => (Number(v) < 0 ? `(${fmt(-v)})` : fmt(v))\n",
  "tests/grants.test.js": "import { describe, expect, it } from 'vitest'\nimport { assetShare, balanced, concessionEntry, emptyForm, imputationEntry, partA, partB, paren, payload, shortTerm, unconditionalEntry, undoable } from '../src/grants'\nimport es from '../src/i18n/es.js'\nimport en from '../src/i18n/en.js'\n\nconst lines = (ls) => ls.map((l) => `${l.account} ${l.debit ? 'D ' + l.debit : 'H ' + l.credit}`).join(' | ')\n\n// Las cifras son las de los supuestos de referencia (docs del proyecto: supuestos-v0.44.0.md; base de datos: fases 59 y 60)\ndescribe('subvenciones · asientos que se ven antes de contabilizar', () => {\n  it('S1 · concesión de capital no reintegrable, con su efecto impositivo', () => {\n    const e = concessionEntry({ ...emptyForm('2026-03-15'), amount: '20.000' })\n    expect(lines(e)).toBe('4708 D 20000 | 940 H 20000 | 8301 D 5000 | 479 H 5000')\n    expect(balanced(e)).toBe(true)\n  })\n  it('S1 · imputación del año (10 %) y S1b · lo que queda al vender', () => {\n    expect(lines(imputationEntry(2000, 500))).toBe('840 D 2000 | 746 H 2000 | 479 D 500 | 8301 H 500')\n    expect(lines(imputationEntry(14000, 3500))).toBe('840 D 14000 | 746 H 14000 | 479 D 3500 | 8301 H 3500')\n  })\n  it('S2 · a la explotación: directa a resultados, con su propia 4708', () => {\n    expect(lines(concessionEntry({ ...emptyForm('2026-05-15'), kind: 'operating', amount: '3000' }))).toBe('47089 D 3000 | 740 H 3000')\n  })\n  it('S3 · reintegrable cobrada (522) y cuando deja de serlo', () => {\n    const f = { ...emptyForm('2026-09-01'), amount: '10000', refundable: true, condition_due: '2027-03-31', collected: true }\n    expect(lines(concessionEntry(f))).toBe('572 D 10000 | 522 H 10000')\n    expect(lines(concessionEntry({ ...f, condition_due: '2028-06-30' }))).toBe('572 D 10000 | 172 H 10000')\n    expect(lines(unconditionalEntry({ kind: 'capital', amount: 10000, tax_rate: 25, grant_date: '2026-09-01', condition_due: '2027-03-31' })))\n      .toBe('522 D 10000 | 940 H 10000 | 8301 D 2500 | 479 H 2500')\n  })\n  it('la subvención financia el 40 % de la máquina', () => {\n    expect([assetShare('20.000', 50000), assetShare('', 50000), assetShare('100', 0)]).toEqual([40, 0, 0])\n  })\n  it('a corto si la condición vence en 12 meses', () => {\n    expect([shortTerm('2026-09-01', '2027-09-01'), shortTerm('2026-09-01', '2027-09-02')]).toEqual([true, false])\n  })\n  it('sin importe, sin asiento; deshacer el último', () => {\n    expect(concessionEntry(emptyForm('2026-01-01'))).toEqual([])\n    expect(undoable([{ id: 'a', seq: 1, status: 'posted' }, { id: 'b', seq: 2, status: 'posted' }, { id: 'c', seq: 3, status: 'cancelled' }])).toBe('b')\n  })\n  it('lo que se manda a la base de datos', () => {\n    const f = { ...emptyForm('2026-03-15'), description: ' Máquina ', grantor: 'Gobierno de Canarias', amount: '20.000', asset_id: 'fa1' }\n    expect(payload(f, 'c')).toEqual({ company_id: 'c', kind: 'capital', date: '2026-03-15', refundable: false, collected: false,\n      description: 'Máquina', grantor: 'Gobierno de Canarias', amount: 20000, tax_rate: 25, asset_id: 'fa1' })\n    expect(payload({ ...f, kind: 'operating' }, 'c').asset_id).toBeUndefined()\n  })\n})\n\ndescribe('ECPN · supuesto S4', () => {\n  const data = {\n    part_a: { result: 30000, b_grants: 20000, b_tax: -5000, b_other: 0, b_total: 15000, c_grants: -2000, c_tax: 500, c_total: -1500, total: 43500 },\n    part_b: { start: { capital: 60000, reserves: 10000, result: 8000 }, other: { reserves: 8000, result: -8000 }, owners: { result: 0 },\n      recognised: { result: 30000, grants: 13500 } },\n    columns: ['capital', 'reserves', 'result', 'grants'], start: 78000, end: 121500, balance_net_worth: 121500, ok: true,\n  }\n  it('parte A: 30.000 + 15.000 − 1.500 = 43.500', () => {\n    expect(partA(data.part_a).map((r) => `${r.key}:${r.amount}`).join(' '))\n      .toBe('result:30000 b_grants:20000 b_tax:-5000 b_total:15000 c_grants:-2000 c_tax:500 c_total:-1500 total:43500')\n  })\n  it('parte B: 78.000 → 121.500 por columnas', () => {\n    const { cols, rows } = partB(data)\n    expect(cols).toEqual(['capital', 'reserves', 'result', 'grants'])\n    expect(rows.map((r) => `${r.key}:${r.total}`).join(' ')).toBe('start:78000 recognised:43500 owners:0 other:0 end:121500')\n    expect(rows.at(-1).values).toEqual({ capital: 60000, reserves: 18000, result: 30000, grants: 13500 })\n  })\n  it('las cifras negativas, entre paréntesis', () => {\n    expect([paren(-1500, String), paren(500, String)]).toEqual(['(1500)', '500'])\n  })\n})\n\ndescribe('subvenciones y ECPN · textos', () => {\n  const keys = (o, p = '') => Object.entries(o).flatMap(([k, v]) => (v && typeof v === 'object' ? keys(v, `${p}${k}.`) : [`${p}${k}`])).sort()\n  it('es y en tienen los mismos textos', () => {\n    expect(keys(en.gr)).toEqual(keys(es.gr))\n    expect(keys(en.ecpn)).toEqual(keys(es.ecpn))\n    expect([es.nav.grants.label, es.nav.ecpn.label]).toEqual(['Subvenciones', 'Cambios en el patrimonio neto'])\n  })\n  it('cada cuenta del asiento y cada fila y columna del ECPN tienen su nombre', () => {\n    for (const k of ['4708', '47089', '940', '740', '522', '172', '8301', '479', '840', '746', '572']) expect(es.gr.account[k], k).toBeTruthy()\n    for (const k of ['result', 'b_grants', 'b_tax', 'b_other', 'b_total', 'c_grants', 'c_tax', 'c_total', 'total']) expect(es.ecpn.a[k], k).toBeTruthy()\n    for (const k of ['start', 'recognised', 'owners', 'other', 'end']) expect(es.ecpn.row[k], k).toBeTruthy()\n    for (const k of ['capital', 'premium', 'reserves', 'prior_results', 'result', 'interim', 'grants']) expect(es.ecpn.col[k], k).toBeTruthy()\n  })\n})\n"
}
